"""作业 8：DQN 及其改进；截图转录与独立解答。"""
def get_questions(p, f, ul):
    return [
    (8,1,'DQN 的基础','以下哪种方法是 DQN 的前身？',['Q-learning','SARSA','Monte Carlo 方法','Actor-Critic 方法'],0,
    p('答案为 A。DQN（Deep Q-Network）以 Q-learning 为基础，用深度神经网络近似动作价值 Q(s,a)，并结合经验回放和目标网络等训练机制。') + f('Q 表 → 参数化动作价值 Q(s,a;θ)') +
    p('SARSA 是同策略 TD 控制，MC 使用完整采样回报，Actor-Critic 同时学习策略与价值；它们都不是本题所问的 DQN 的直接基础。'),
    '从表格到函数近似',p('Q 表为每个状态—动作对保存数值；网络通过共享参数处理高维或连续状态，并在状态间泛化。标准 DQN 通常一次输出有限离散动作的全部 Q 值。连续状态可处理，不代表连续动作也能直接枚举。')),
    (8,2,'DQN 的稳定训练机制','DQN 中使用哪种方法解决 Q 值估计的不稳定性问题？',['经验回放','目标网络','A 和 B 都不是','A 和 B 都是'],3,
    p('答案为 D。经验回放与目标网络共同缓解训练不稳定，但作用不同。') + ul('经验回放：存储转移，随机抽取小批量训练，减弱连续样本的时间相关性，并复用经验。','目标网络：用更新较慢的网络构造 TD 目标，减少目标与当前预测同时快速变化的问题。') +
    p('两者是稳定化机制，不代表对任意任务、超参数和网络都能保证收敛。'),
    '数据相关性与移动目标',p('随机回放主要改变训练数据的抽样方式；目标网络主要改变自举目标的生成方式。两者分别处理数据与目标两方面的问题，不能互相简单替代。')),
    (8,3,'DQN 的改进算法','下列哪些算法是 DQN 基础上的改进算法？',['DDQN','Dueling DQN','SAC','PPO'],(0,1),
    p('答案为 A、B。这里 DDQN 指 Double DQN。它改进目标计算以缓解过高估计；Dueling DQN 改进网络结构，分别学习状态价值和动作优势。') +
    p('SAC 是最大熵框架下的 Actor-Critic 算法，PPO 属于策略优化方法。它们是深度强化学习算法，但通常不归类为 DQN 的直接改进版本。'),
    'Double 与 Dueling 可以组合',p('Double 改的是动作选择与评价的分工；Dueling 改的是 Q 网络内部的表示结构。两种机制并不冲突，也可与优先经验回放组合。名称相近，不代表解决的是同一个问题。')),
    (8,4,'目标网络的作用','DQN 中的目标网络（Target Network）是用来解决什么问题的？',['网络的过拟合问题','网络的梯度消失问题','网络的 Q 值估计不稳定问题','网络的训练速度过慢问题'],2,
    p('答案为 C。在线网络参数记为 θ，目标网络参数记为 θ⁻。标准 DQN 用目标网络生成相对稳定的训练目标：') +
    f('y = r + γ(1−d) max<sub>a′</sub> Q(s′,a′;θ⁻)<br>L(θ) = E[(y − Q(s,a;θ))²]') +
    p('d=1 表示真正终止。训练时不对目标 y 反向传播；在线网络持续更新，目标网络按固定间隔复制在线参数。这样可缓解“预测在变、目标也跟着立即变”的反馈。它不是专门解决过拟合、梯度消失或计算速度的方法。'),
    '硬更新与软更新',p('经典 DQN 常用周期性硬更新 θ⁻←θ；一些实现使用软更新 θ⁻←τθ+(1−τ)θ⁻。更新过频会减弱稳定目标的作用，过慢则可能使目标陈旧，需要按任务选择。外部时间截断不一定是真正终止，应依据任务定义决定是否继续自举。')),
    (8,5,'经验回放的含义','DQN 中的经验回放是什么？',['在每次训练中只使用最新的经验','在训练时将之前的经验随机抽样并重复使用','在训练时将之前的经验按时间顺序使用','在训练时将之前的经验按优先级使用'],1,
    p('答案为 B，按标准均匀经验回放理解。智能体把 (s,a,r,s′,done) 存入缓冲区，再从中随机抽取小批量进行训练，同一条转移可以在不同更新中多次使用。') +
    ul('A 不符合经验复用的含义。','B 对应经典 DQN 的随机回放。','C 按时间顺序使用，未体现随机抽样以减弱时间相关性的作用。','D 对应优先经验回放这一扩展，不是本题标准均匀回放的预期答案。'),
    '缓冲区不是无限存档',p('实际回放缓冲区通常容量有限，旧数据会被替换。随机抽样减弱相邻更新之间的相关性，并不把所有样本变成严格独立同分布。数据过旧、覆盖不足或抽样偏差仍可能影响学习。')),
    (8,6,'Double DQN 改进了什么','DDQN 相较于 DQN 的改进就是首创了目标网络。',['对','错'],1,
    p('答案为 B，错。目标网络在标准 DQN 中已经存在。Double DQN 的关键是将下一动作的选择和该动作的价值评价分开：') +
    f('a* = arg max<sub>a′</sub> Q(s′,a′;θ)<br>y<sub>DDQN</sub> = r + γ(1−d)Q(s′,a*;θ⁻)') +
    p('在线网络选择动作，目标网络评价所选动作。标准 DQN 则直接在目标网络输出上取最大值。分离选择与评价旨在缓解最大化操作引入的过高估计。'),
    '数值对比',p('若在线网络对两个动作的估计为 [5,4]，目标网络估计为 [3,6]，Double DQN 选第一个动作，并用目标网络的 3 评价；标准 DQN 直接取目标网络的最大值 6。设 r=1、γ=0.9 且未终止，两者目标分别为 3.7 与 6.4。Double DQN 缓解高估，不保证每一步完全无偏。')),
    (8,7,'Dueling DQN 的核心思想','Dueling DQN 的主要思想是什么？',['对动作价值函数进行分解','对状态价值函数进行分解','对策略函数进行分解','对优势函数进行分解'],0,
    p('答案为 A。Dueling 网络将动作价值 Q 的表示分为状态价值分支与动作优势分支，再聚合成每个动作的 Q 值。常见的均值中心化形式为：') +
    f('Q(s,a) = V(s) + A(s,a) − (1/|𝒜|)∑<sub>b∈𝒜</sub>A(s,b)') +
    p('V 分支表示状态整体价值，A 分支区分动作的相对好坏；被分解的整体是动作价值 Q，而不是策略。'),
    '为什么要减去优势均值？',p('若只写 Q=V+A，则 V 加一个常数、A 减同一常数，Q 不变，分解有冗余。优势中心化给聚合形式增加约束。比如 V=10、原始优势为 [2,0,−2]，均值为 0，Q=[12,10,8]。网络分支的 V 不应无条件等同于任意给定策略下的理论 V<sup>π</sup>；这是一个表示结构。')),
    (8,8,'优先经验回放的优势','优先经验回放相较于传统经验回放的优势主要在于提高学习效率。',['对','错'],0,
    p('答案为 A，对。优先经验回放（PER）将更多更新机会分配给当前更值得学习的转移，常以 TD 误差绝对值衡量优先级，以提高样本利用效率。') +
    p('它仍然进行随机抽样，只是抽样概率不再均匀。“提高学习效率”是设计目的与常见收益，不代表所有任务中都一定更快。'),
    '样本效率与运行时间不同',p('维护优先级和抽样结构会增加计算开销。用更少交互样本达到同等表现，不等于每次梯度更新耗时更短。非均匀抽样还改变数据分布，通常需要重要性采样权重修正。')),
    (8,9,'TD 误差与优先级','在优先经验回放中，TD 误差越小的样本具有更高的优先级。',['对','错'],1,
    p('答案为 B，错。常见 PER 让 TD 误差绝对值较大的样本具有较高优先级，而不是较小的样本。比例式优先回放常写为：') +
    f('δᵢ = yᵢ − Q(sᵢ,aᵢ;θ)<br>pᵢ = |δᵢ| + ε<sub>p</sub><br>P(i) = pᵢ<sup>α</sup> / ∑ⱼpⱼ<sup>α</sup>') +
    p('εₚ 是防止优先级为零的小常数，不是 ε-greedy 的探索概率。这里 α 控制优先程度，不是学习率；α=0 时退化为均匀抽样。误差 −5 的绝对值大于误差 +1，因此在其他条件相同时前者优先级更高。'),
    '抽样偏差与重要性权重',f('wᵢ = [1 / (N·P(i))]<sup>β</sup>') +
    p('N 为缓冲区样本数，β 控制修正强度；实践中还常对权重归一化。高概率样本的更新权重相对较小。TD 误差大也可能来自噪声，并非总能学到有用信息，且优先级需要随价值更新刷新。')),
    (8,10,'DQN 的探索方式','在 DQN 算法中，采用哪种方法来平衡探索和利用？',['Epsilon-greedy exploration','Softmax exploration','Upper confidence bound exploration','Thompson sampling'],0,
    p('答案为 A。经典 DQN 常采用 ε-greedy：以 ε 的概率随机选择动作，以 1−ε 的概率选择当前 Q 估计最大的动作。训练中 ε 经常逐渐降低。') +
    f('唯一贪心动作、n 个可选动作：<br>P(贪心动作) = 1−ε+ε/n') +
    p('Softmax、UCB 与 Thompson sampling 也是探索思路，但不是本题所问的经典 DQN 默认方案。'),
    '探索方式不是 Q 更新公式本身',p('ε-greedy 是常见行为策略，并非所有 DQN 扩展只能用它。目标中的 max 与实际采样动作的规则应分开理解；即使行为中包含探索，学习目标仍可针对贪心选择，这体现了异策略学习。')),
    (8,11,'DQN 的性质辨析','下列关于 DQN 的说法中，正确的是？',['DQN 存在过高估计问题。','DQN 是一种同策略算法。','DQN 中的经验回放用于打破样本之间的关联性。','DQN 可以用于处理连续动作空间问题。'],(0,2),
    p('答案为 A、C，按标准 DQN 理解。') +
    ul('<b>A 对：</b>对有噪声的动作价值估计取最大值，会偏好被高估的动作；DQN 可能出现过高估计，并不表示每个值都必然高估。','<b>B 错：</b>DQN 是异策略算法。行为策略可带探索，学习目标使用贪心动作价值。','<b>C 对：</b>随机经验回放用于减弱时间相关性；“打破关联性”是教学简写，不保证数据严格独立。','<b>D 不选：</b>标准 DQN 面向有限离散动作。连续动作无法直接用有限输出枚举并取 max，需要离散化或其他扩展。'),
    '连续状态不等于连续动作',p('图像或连续向量状态可以作为网络输入；动作若是有限离散选项，仍适合标准 DQN。若动作是任意实数向量，如连续转矩，需要额外处理动作最大化，常采用适合连续控制的 Actor-Critic 方法。')),
    (8,12,'DQN 是否使用纯贪心策略','DQN 算法使用贪心策略来选择动作，这个说法正确还是错误？',['对','错'],1,
    '<p class="note">建议答案 B，错。按本组题第 10 题的训练语境，将“贪心策略”理解为每一步都纯贪心。若题目专指评估阶段，则可以采用纯贪心，原句未区分阶段。</p>' +
    p('经典 DQN 训练通常采用 ε-greedy 行为策略，在利用当前估计的同时保留探索。只按 arg max 选动作是 ε=0 的特殊情况，不代表一般训练过程。') +
    f('训练：a ∼ ε-greedy(Q(s,·;θ))<br>常见评估：a ∈ arg max<sub>a′</sub> Q(s,a′;θ)') +
    p('因此，第 10 题选 ε-greedy 与本题判断为错并不矛盾。也不应反过来说“DQN 永远不能使用纯贪心”。'),
    '三种容易混淆的选择',ul('行为选择：本次交互实际执行哪个动作，训练时常带探索。','目标选择：构造 TD 目标时选择哪个后继动作，标准 DQN 使用目标网络上的 max。','评估选择：检验训练后的策略时如何选动作，常关闭探索，也可能按评测协议保留少量随机性。')),
    ]

RECAP = '''<section id="dqn-recap"><div class="eyebrow">DEEP Q-LEARNING / 复习卡</div><h2>区分 DQN 的四类改进</h2><table><caption>机制与作用</caption><thead><tr><th>机制</th><th>改变什么</th><th>主要目的</th></tr></thead><tbody><tr><td>经验回放</td><td>数据抽样与复用</td><td>减弱时间相关性，提高样本利用</td></tr><tr><td>目标网络</td><td>自举目标的更新节奏</td><td>缓解目标快速变化引起的不稳定</td></tr><tr><td>Double DQN</td><td>分开动作选择与评价</td><td>缓解最大化导致的高估</td></tr><tr><td>Dueling DQN</td><td>Q 的网络表示结构</td><td>分别学习状态价值与动作优势</td></tr><tr><td>优先经验回放</td><td>样本抽取概率与更新权重</td><td>优先利用有学习价值的转移</td></tr></tbody></table><p>记忆：Double 改目标，Dueling 改结构，PER 改抽样。目标网络不是 Double DQN 首创；DQN 是无模型、异策略的价值学习算法。标准动作空间是离散的，训练行为通常采用 ε-greedy。</p><p>题目来源：用户提供的四张截图，共 12 题；第 3、11 题为多选。答案与解析为独立解答，非官方答案。第 5 题按均匀经验回放作答；第 12 题按训练时是否纯贪心作答，评估阶段可以不同。</p><p>原始论文：<a href="https://www.nature.com/articles/nature14236">DQN：Human-level control through deep reinforcement learning</a>；<a href="https://arxiv.org/abs/1509.06461">Double DQN</a>；<a href="https://proceedings.mlr.press/v48/wangf16.html">Dueling Network Architectures</a>；<a href="https://arxiv.org/abs/1511.05952">Prioritized Experience Replay</a>。</p></section>'''
